function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // box
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // lever
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2-20, H/2+40, 10, 20);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-30, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-20);
  ctx.lineTo(W/2, H/2+10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-10);
  ctx.lineTo(W/2-15, H/2+10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-10);
  ctx.lineTo(W/2+15, H/2+10);
  ctx.stroke();

  // reward/punishment
  if (Math.sin(t) > 0) {
    ctx.fillStyle = 'green';
    ctx.fillRect(W/2+60, H/2-20, 10, 10);
    ctx.fillStyle = 'black';
    ctx.font = '14px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText('+', W/2+70, H/2-20);
  } else {
    ctx.fillStyle = 'red';
    ctx.fillRect(W/2+60, H/2-20, 10, 10);
    ctx.fillStyle = 'black';
    ctx.font = '14px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText('-', W/2+70, H/2-20);
  }

  // action
  if (Math.sin(t) > 0.5) {
    ctx.beginPath();
    ctx.moveTo(W/2-10, H/2+10);
    ctx.lineTo(W/2-20, H/2+40);
    ctx.stroke();
  }

  ctx.restore();
}
